OrdersService.create.source:
async create(dto: CreateOrderDto): Promise<Order> {
  const quote = await this.pricing.quote(dto.lines, dto.country);
  const risk = await this.fraud.score({ customerId: dto.customerId, country: dto.country, total: quote.total });
  const held = needsReview(risk, quote.total);
  if (!held) await this.inventory.reserve(dto.lines);
  const order = await this.orders.save({ ...dto, status: held ? 'held' : 'pending', total: quote.total });
  if (held) {
    this.kafka.emit('orders.held', { orderId: order.id, risk });
    return order;
  }
  this.kafka.emit('orders.created', { orderId: order.id, total: order.total });
  this.events.emit('order.created', order);
  return order;
}

PricingService.quote.source:
async quote(lines: OrderLine[], country: string): Promise<Quote> {
  const products = await this.products.findBy({ id: In(lines.map((l) => l.productId)) });
  const subtotal = lines.reduce((sum, l) => sum + (products.find((p) => p.id === l.productId)?.price ?? 0) * l.quantity, 0);
  const rate = await this.tax.rateFor(country);
  return { subtotal, tax: round(subtotal * rate), total: round(subtotal * (1 + rate)) };
}

