InventoryService.reserve.source:
async reserve(lines: OrderLine[]): Promise<void> {
  for (const line of lines) {
    const item = await this.stock.findOneBy({ productId: line.productId });
    if (!item || item.available < line.quantity) throw new ConflictException(`out of stock: ${line.productId}`);
    await this.stock.update({ productId: line.productId }, { available: item.available - line.quantity, reserved: item.reserved + line.quantity });
  }
}

OrdersService.release.source:
async release(id: string): Promise<Order> {
  const order = await this.get(id);
  if (order.status !== 'held') throw new NotFoundException(`order ${id} is not held`);
  await this.inventory.reserve(order.lines);
  await this.orders.update({ id }, { status: 'pending' });
  this.kafka.emit('orders.created', { orderId: id, total: order.total });
  this.events.emit('order.created', order);
  return { ...order, status: 'pending' };
}

OrdersService.get.source:
async get(id: string): Promise<Order> {
  const order = await this.orders.findOneBy({ id });
  if (!order) throw new NotFoundException(`order ${id}`);
  await this.views.insert({ orderId: id });
  return order;
}

OrdersService.cancel.source:
async cancel(id: string): Promise<Order> {
  const order = await this.get(id);
  if (order.status === 'paid') await this.payments.refund(order);
  await this.inventory.release(order.lines);
  await this.orders.update({ id }, { status: 'cancelled' });
  this.kafka.emit('orders.cancelled', { orderId: id });
  return { ...order, status: 'cancelled' };
}

PaymentsService.refund.source:
async refund(order: Order): Promise<void> {
  await firstValueFrom(this.http.post('https://api.payments.example/v1/refunds', { orderId: order.id, amount: order.total }));
  await this.payments.update({ orderId: order.id }, { status: 'refunded' });
}

InventoryService.release.source:
async release(lines: OrderLine[]): Promise<void> {
  for (const line of lines) {
    await this.stock.increment({ productId: line.productId }, 'available', line.quantity);
    await this.stock.decrement({ productId: line.productId }, 'reserved', line.quantity);
  }
}

PaymentsService.handleWebhook.source:
async handleWebhook(event: ProviderEvent): Promise<Payment> {
  const status = event.type === 'charge.succeeded' ? 'succeeded' : 'failed';
  const payment = await this.payments.save({ id: event.paymentId, orderId: event.orderId, status, amount: event.amount });
  if (status === 'succeeded') await this.receipts.add('send-receipt', { paymentId: payment.id });
  return payment;
}
